def _load_policy_schema() -> tuple[set, set, set]:
    """Load receipt_schema from the cached policy.json if available.

    Returns (required_fields, valid_roles, valid_backends) — falling back to
    hardcoded defaults when the cache is absent or missing the receipt_schema key.

    #198: ``valid_roles`` is the UNION of the policy's list and the built-in
    defaults, not a replacement. The policy may widen the accepted set; it may
    not narrow it below the roles this plugin itself emits.

    Two reasons. First, published policy version 1 lists nine roles and omits
    `orchestrator`, which the orchestrator legitimately writes (4 such receipts
    in prod) and which server-side analytics accept as a stage — so every
    machine that had fetched the policy warned on a correct receipt, while CI,
    having no cache, did not. That made ``./synaptory test`` pass in CI and fail
    on a logged-in laptop: a test suite whose result depends on login state is
    worse than the warning itself.

    Second, ``VALID_ROLES`` drives a *warning*, never a rejection, so widening
    costs nothing while narrowing produces false alarms. The trade-off is
    explicit: a future policy cannot retire a role by omission alone. Retiring
    one means removing it from ``_DEFAULT_VALID_ROLES`` too — which is exactly
    how `product-manager` was retired (see ``_RETIRED_ROLES``).
    """
    from host_env import state_dir

    cache_path = os.path.join(state_dir(), ".cache", "policy.json")
    try:
        with open(cache_path, "r") as f:
            cached = json.load(f)
        schema = cached.get("payload", {}).get("receipt_schema", {})
        required = set(schema.get("required_fields", [])) or _DEFAULT_REQUIRED_FIELDS
        roles = set(schema.get("valid_roles", [])) | _DEFAULT_VALID_ROLES
        # Union, not replace — a published policy that only lists `claude`
        # must not make Cursor-host receipts (`cursor`/`codex`/`gemini`) warn.
        backends = set(schema.get("valid_backends", [])) | _DEFAULT_VALID_BACKENDS
        return required, roles, backends
    except (FileNotFoundError, json.JSONDecodeError, KeyError):
        return _DEFAULT_REQUIRED_FIELDS, _DEFAULT_VALID_ROLES, _DEFAULT_VALID_BACKENDS


REQUIRED_FIELDS, VALID_ROLES, VALID_BACKENDS = _load_policy_schema()

# story_id pattern: US-NNN, TICKET-NNN, INFRA-NNN, BUG-NNN, etc.
STORY_ID_PATTERN = re.compile(r"^[A-Z][A-Z0-9]*-\d+$")


def infer_backend_from_model(model: str) -> Optional[str]:
    """Map a model id to its provider family without guessing `claude`.

    This is not always the receipt ``backend``. Cursor is a runtime/router and
    can truthfully report a model supplied by Claude, Gemini, or OpenAI while
    retaining ``backend: cursor``. Returns None when the id is empty or
    unrecognized (omit rather than invent).
    """
    m = (model or "").strip().lower()
    if not m:
        return None
    if "claude" in m or m.startswith("anthropic"):
        return "claude"
    if "gemini" in m:
        return "gemini"
    if (
        "codex" in m
        or m.startswith("gpt-")
        or m.startswith("o1")
        or m.startswith("o3")
        or m.startswith("o4")
    ):
        return "codex"
    if "composer" in m or "grok" in m or "cursor" in m:
        return "cursor"
    return None


class ValidationResult:
    """Result of receipt validation."""

    def __init__(self) -> None:
        self.valid = True
        self.errors: list[str] = []
        self.warnings: list[str] = []

    def error(self, msg: str) -> None:
        self.errors.append(msg)
        self.valid = False

    def warn(self, msg: str) -> None:
        self.warnings.append(msg)

    def to_dict(self) -> dict[str, Any]:
        return {
            "valid": self.valid,
            "errors": self.errors,
            "warnings": self.warnings,
        }


#: Historical marker inspection retained for compatibility. This helper does
#: not grade receipt admissibility: bare strings remain readable as legacy
#: identities, while model_identity validates versioned typed observations.
UNATTRIBUTED_MODEL_SUFFIX = "-runtime-unattributed"


def model_names_no_model(model: object) -> bool:
    """Is this model id a placeholder rather than an identity?"""
    text = str(model or "").strip().lower()
    return not text or text.endswith(UNATTRIBUTED_MODEL_SUFFIX)


def validate_receipt(receipt_path: str, project_dir: str) -> ValidationResult:
    """Validate a receipt JSON file against the v2 receipt protocol schema.

    Args:
        receipt_path: Absolute path to receipt JSON file.
        project_dir: Project root directory (for resolving artifact paths).

    Returns:
        ValidationResult with valid flag, errors list, and warnings list.
    """
    result = ValidationResult()

    try:
        with open(receipt_path, "r") as f:
            receipt = json.load(f)
    except FileNotFoundError:
        result.error(f"Receipt file not found: {receipt_path}")
        return result
    except json.JSONDecodeError as e:
        result.error(f"Invalid JSON in receipt: {e}")
        return result

    return validate_receipt_payload(receipt, project_dir)


#: The payload key carrying typed DoD check results. The control plane reads
#: the same key (`analytics.DOD_CHECK_RESULTS_KEY`), which #407 named as this
#: ticket's seam, so the two spellings must stay identical.
DOD_CHECK_RESULTS_KEY = "dod_check_results"

#: The payload key carrying typed evidence items.
EVIDENCE_KEY = "evidence"


def _validate_typed_evidence(receipt: dict, result: "ValidationResult") -> None:
    """Refuse a typed-evidence claim whose discipline is unmet (#403).

    Two optional blocks, both opt-in: no receipt is required to carry either,
    and a receipt that carries neither validates exactly as before. But once a
    block IS present, every item in it is checked against the discipline its
    own `evidence_class` (or its `result` value) names, because the claim is
    what a reader would otherwise credit.

    Severity is `error`, not `warn`.

    #403 landed that severity leaning on a migration window it did not own:
    `advance_kernel.RECEIPT_INVALID` was a member of `_EVIDENCE_CODES`, so a
    host running `enforcement="warn"` downgraded this refusal to a warning
    while a structured-mode host refused. #755 closed that window, because the
    window is what the defect travelled through: on the #714 pilot Cycle a
    receipt carrying three bare class tokens -- a `replayed` item naming no
    command, an `attested` item naming no attempt, a `judged` item naming no
    principal -- advanced a Work Unit past its producer stage while this
    validator, in the same build, reported the same document invalid.

    So an error here is now an error at the gate on every host. The route out
    of an inadmissible receipt is #741's recovery ladder (a fresh dispatch,
    with the invalid bytes archived and never edited), not a warning.
    """
    has_evidence = EVIDENCE_KEY in receipt
    has_typed_results = DOD_CHECK_RESULTS_KEY in receipt
    if not has_evidence and not has_typed_results:
        return
    if _runtime_contracts is None:  # pragma: no cover - partial install
        result.warn(
            f"'{EVIDENCE_KEY}'/'{DOD_CHECK_RESULTS_KEY}' present but the "
            "runtime_contracts module is not importable, so no evidence-class "
            "discipline could be checked. Treat every class claim in this "
            "receipt as unbacked."
        )
        return

    if has_evidence:
        evidence = receipt[EVIDENCE_KEY]
        if not isinstance(evidence, list):
            result.error(
                f"'{EVIDENCE_KEY}' must be a list of typed evidence items, "
                f"got: {type(evidence).__name__}"
            )
        else:
            for i, item in enumerate(evidence):
                for problem in _runtime_contracts.validate_evidence_item(item):
                    result.error(f"{EVIDENCE_KEY}[{i}] {problem}")

    if has_typed_results:
        typed = receipt[DOD_CHECK_RESULTS_KEY]
        if not isinstance(typed, list):
            result.error(
                f"'{DOD_CHECK_RESULTS_KEY}' must be a list of DoD check "
                f"results, got: {type(typed).__name__}"
            )
        else:
            for i, item in enumerate(typed):
                for problem in _runtime_contracts.validate_dod_check_result(item):
                    result.error(f"{DOD_CHECK_RESULTS_KEY}[{i}] {problem}")
            # A receipt-supplied check result is SELF-REPORTED. It is recorded
            # and rendered; it never becomes the pipeline's verdict and never
            # clears a gate (#445). Say so once, where the writer will read it,
            # so nobody ships one expecting it to count as evidence.
            if isinstance(typed, list) and typed:
                result.warn(
                    f"'{DOD_CHECK_RESULTS_KEY}' is recorded as SELF-REPORTED: "
                    "the DoD gate uses the verdict it computes from evidence, "
                    "so a result posted here refines the record but never "
                    "clears or blocks a check. Put the proof in "
                    "`verification_commands` / `metrics` instead."
                )


#: The #342 runtime-identity overlay pair, in the order the refusal names it.
#: On a governed dispatch the kernel hands both values over on
#: `dispatch_envelope.stage_profile` / `dispatch_envelope.capability_profile`,
#: which since #471 is verified against control-plane-signed bytes rather than
#: against the local proposal. They are copied, never chosen.
OVERLAY_PAIR = ("stage_profile", "capability_profile")

#: Where the agent reads each overlay value from on a governed dispatch. The
#: refusal names the field rather than the value, because naming the value
#: would be telling the agent what to write instead of where to read it.
OVERLAY_ENVELOPE_FIELD = {
    "stage_profile": "dispatch_envelope.stage_profile",
    "capability_profile": "dispatch_envelope.capability_profile",
}


def _overlay_absent(receipt: dict, field: str) -> bool:
    """True when `field` carries no readable overlay value.

    Absent, or a string that strips to empty — the same two cases
    `advance_kernel._overlay_value` treats as absence, so the two modules
    cannot disagree about what "the agent did not stamp one" means.

    A PRESENT non-string is deliberately NOT absence here. It is a claim in an
    unreadable shape, and the kernel already refuses it as `PROFILE_MISMATCH`
    with a message that says so; reporting it here as "missing" would replace
    a precise refusal with a misleading one.
    """
    if field not in receipt:
        return True
    raw = receipt[field]
    return isinstance(raw, str) and not raw.strip()


def _governed_dispatch_authority(receipt: dict, project_dir: str) -> tuple:
    """`(pipeline_abbrev, authority)` for the dispatch that produced this receipt.

    `pipeline_abbrev` is "" for a role that no receipt-gated pipeline edge is
    bound to (technical-writer, orchestrator, research-advisor, …): those
    receipts are outside the overlay contract entirely, so they get neither
    the refusal nor the reminder. It is derived from the kernel's own
    `TRANSITION_RECEIPT` table rather than listed here, so a table change moves
    the scope with it.

    `authority` is `{}` when the dispatch was not governed, meaning no envelope
    was handed over.

    THE SIGNAL COMES FROM THE DISPATCHER, NOT FROM THE RECEIPT AND NOT FROM
    THE CONFIG. Two rejected alternatives, and the reasons are the design:

    * **From the receipt.** Any field the agent writes — `attempt_id`, an
      embedded envelope, a `governed: true` flag — makes the REQUIREMENT
      itself forgeable by omission: drop the field that marks the dispatch as
      governed and the pair stops being required. That is the exact incentive
      inversion this ticket exists to remove, so the receipt is not consulted
      for anything except which (story, stage) to look up.
    * **From the config.** Re-reading `runtimes:`, the probe snapshot and the
      profile registry answers for the tree as it is NOW, and all three can
      move between dispatch and validation. A validator deciding "governed"
      differently from the dispatcher would refuse honest receipts and admit
      dishonest ones.

    `advance_kernel.governed_dispatch_authority` reads the runtime selection
    the dispatch persisted on the stage's binding, which is the same field
    `evaluate_advance` uses to decide which executor was authorized. One
    field, one writer, two readers.
    """
    story_id = receipt.get("story_id")
    role = receipt.get("role")
    if not isinstance(story_id, str) or not isinstance(role, str):
        return "", {}
    try:
        # Lazy, and one-directional: the kernel imports THIS module inside
        # `evaluate_advance` for the same reason, so neither import runs at
        # module load and the pair cannot cycle.
        import advance_kernel  # type: ignore

        abbrev = advance_kernel.role_abbrev(role)
        gated = {bound[1] for bound in advance_kernel.TRANSITION_RECEIPT.values()}
        if not abbrev or abbrev not in gated:
            return "", {}
        return abbrev, advance_kernel.governed_dispatch_authority(
            project_dir, story_id, abbrev
        )
    except Exception:  # noqa: BLE001 - validation must not crash on the kernel
        return "", {}


def _validate_runtime_identity_overlay(
    receipt: dict, project_dir: str, result: "ValidationResult"
) -> None:
    """Require the #342 overlay pair on a governed dispatch's receipt (#473).

    What requiring presence does and does not buy is worth stating where the
    code is. It does NOT make the pair trustworthy: the agent still types it.
    What makes it load-bearing is that `advance_kernel.profile_overlay_problems`
    compares a present pair against the transition edge and refuses a
    contradiction (#402). Before this function, ABSENCE was the cheapest way
    to avoid that comparison — omit the pair and there is nothing to compare.
    Closing that is the whole point: on a governed dispatch, omission now costs
    a refusal instead of a warning, so declaring the pair honestly is the
    cheapest remaining option and every declared pair meets the edge.
    """
    missing = [field for field in OVERLAY_PAIR if _overlay_absent(receipt, field)]
    if not missing:
        return
    abbrev, authority = _governed_dispatch_authority(receipt, project_dir)
    if not abbrev:
        # Not a role any receipt-gated pipeline edge is bound to, so the
        # overlay contract does not reach it. Silence rather than a reminder:
        # this validator's output is read by an agent under a token budget.
        return
    named = ", ".join("'%s'" % field for field in missing)
    if not authority:
        # Ungoverned: no envelope was handed over, so there was nothing to
        # copy. Unchanged from #342/#402 — a warning, and on a receipt-gated
        # edge the advance kernel emits its own `profile_overlay_absent` too.
        result.warn(
            "%s missing — the #342 runtime-identity overlay is soft-required "
            "here because this dispatch recorded no governed runtime "
            "selection, so no dispatch envelope carried the pair. It is "
            "REQUIRED on a governed dispatch (#473)." % named
        )
        return
    result.error(
        "%s missing on a governed dispatch's receipt. This dispatch was "
        "authorized under runtime profile %s, so the kernel handed the agent a "
        "dispatch envelope carrying the runtime-identity overlay: copy "
        "VERBATIM from %s. Do not derive or choose either value — the advance "
        "gate keys the stage on the pair and refuses one that names another "
        "(#402), and omitting it is not a way around that check (#473)."
        % (
            named,
            authority.get("adapter_profile_id") or authority["runtime_family"],
            " and ".join(OVERLAY_ENVELOPE_FIELD[field] for field in missing),
        )
    )


def validate_receipt_payload(receipt: Any, project_dir: str) -> ValidationResult:
    """Validate an already-parsed receipt object.

    Callers that have read the file once (the advance kernel hashes those
    same bytes) must validate this payload rather than reopening the path,
    otherwise the digest and the validated receipt can describe different
    on-disk content.
    """
    result = ValidationResult()
    if not isinstance(receipt, dict):
        result.error("Receipt must be a JSON object")
        return result

    # Check required fields
    missing = REQUIRED_FIELDS - set(receipt.keys())
    if missing:
        result.error(f"Missing required fields: {', '.join(sorted(missing))}")

    # Validate story_id
    if "story_id" in receipt:
        story_id = receipt["story_id"]
        if not isinstance(story_id, str) or not story_id.strip():
            result.error("'story_id' must be a non-empty string")
        elif not STORY_ID_PATTERN.match(story_id):
            result.warn(
                f"'story_id' format '{story_id}' does not match expected pattern "
                "(e.g., US-001, TICKET-042, INFRA-003)"
            )

    # Validate role
    if "role" in receipt:
        role = receipt["role"]
        if not isinstance(role, str):
            result.error("'role' must be a string")
        elif role in _RETIRED_ROLES:
            # Naming the successor matters here: this value is rejected by a DB
            # CHECK constraint at ingest, so a generic "unrecognized" warning
            # would leave the writer guessing why the receipt later vanished.
            result.warn(
                f"Retired role: '{role}' — use "
                f"'{_RETIRED_ROLES[role]}' instead. The control plane REJECTS "
                f"'{role}' at ingest (ADR-019; constraint "
                "ck_receipts_no_legacy_product_manager), so this receipt will "
                "not be recorded."
            )
        elif role not in VALID_ROLES:
            result.warn(
                f"Unrecognized role: '{role}' (expected one of {sorted(VALID_ROLES)})"
            )

    # Validate backend
    if "backend" in receipt:
        backend = receipt["backend"]
        if not isinstance(backend, str):
            result.error("'backend' must be a string")
        elif backend not in VALID_BACKENDS:
            result.warn(
                f"Unrecognized backend: '{backend}' (expected one of {sorted(VALID_BACKENDS)})"
            )

    # Typed identities carry source semantics and a measured binary version.
    # Legacy strings remain readable; readers never promote them to vendor IDs.
    if "model" in receipt:
        from model_identity import identity_problems
        for problem in identity_problems(receipt):
            result.error(problem)
        if isinstance(receipt["model"], str) and not receipt["model"].strip():
            result.warn("'model' is empty — legacy identity is unavailable")

    # Honest backend↔model mapping (Cursor Router + multi-host receipts).
    # `backend` identifies the runtime host/router. Only a vendor ID (or the
    # legacy string) supports this inference. Cursor can route to other providers,
    # so a provider-shaped model does not contradict `backend: cursor`.
    # The reverse remains false: `composer-*` / `grok-*` with
    # `backend: claude` is a lie and fails closed.
    backend_val = receipt.get("backend")
    model_val = receipt.get("model")
    if isinstance(model_val, dict):
        model_val = model_val.get("value") if model_val.get("kind") == "vendor_id" else None
    if isinstance(backend_val, str):
        backend_val = {"claude-code": "claude", "cursor-agent": "cursor"}.get(backend_val, backend_val)
    if isinstance(backend_val, str) and isinstance(model_val, str) and model_val.strip():
        inferred = infer_backend_from_model(model_val)
        if inferred and inferred != backend_val and backend_val != "cursor":
            result.error(
                f"backend '{backend_val}' does not match model '{model_val}' "
                f"(inferred backend '{inferred}'). Do not invent backend: claude."
            )

    # Validate artifacts
    if "artifacts" in receipt:
        artifacts = receipt["artifacts"]
        if not isinstance(artifacts, list):
            result.error("'artifacts' must be a list")
        elif len(artifacts) == 0:
            result.error("'artifacts' must be non-empty — list every file the agent produced")
        else:
            for artifact_path in artifacts:
                if not isinstance(artifact_path, str):
                    result.error(f"Artifact path must be string, got: {type(artifact_path).__name__}")
                    continue
                full_path = os.path.join(project_dir, artifact_path)
                if not os.path.exists(full_path):
                    result.error(f"Artifact not found on disk: {artifact_path}")
                elif os.path.isfile(full_path) and os.path.getsize(full_path) == 0:
                    result.error(f"Artifact is empty (0 bytes): {artifact_path}")

    # Validate metrics
    if "metrics" in receipt:
        metrics = receipt["metrics"]
        if not isinstance(metrics, dict):
            result.error("'metrics' must be a dict")
        elif len(metrics) == 0:
            result.error("'metrics' must be non-empty — include at least one concrete number")

    # Required: verification_commands — every agent must provide machine-verifiable proof
    if "verification_commands" in receipt:
        cmds = receipt["verification_commands"]
        if not isinstance(cmds, list):
            result.error("'verification_commands' must be a list")
        elif len(cmds) == 0:
            result.error(
                "'verification_commands' must contain at least one command. "
                "Include commands that prove your work (e.g., test runner, build, file checks)."
            )
        else:
            for i, cmd in enumerate(cmds):
                if isinstance(cmd, str):
                    # v2 simple string format — accepted
                    if not cmd.strip():
                        result.error(f"verification_commands[{i}] is an empty string")
                elif isinstance(cmd, dict):
                    # Legacy dict format — still accepted for transition
                    cmd_missing = {"command", "exit_code", "summary"} - set(cmd.keys())
                    if cmd_missing:
                        result.error(
                            f"verification_commands[{i}] (dict) missing fields: {', '.join(sorted(cmd_missing))}"
                        )
                else:
                    result.error(
                        f"verification_commands[{i}] must be a string or dict, "
                        f"got: {type(cmd).__name__}"
                    )

    # Validate completed_at
    if "completed_at" in receipt:
        completed_at = receipt["completed_at"]
        if not isinstance(completed_at, str) or not completed_at.strip():
            result.error("'completed_at' must be a non-empty ISO 8601 timestamp string")

    # Optional: confidence (recommended for controlled mode)
    if "confidence" in receipt:
        confidence = receipt["confidence"]
        if not isinstance(confidence, dict):
            result.warn("'confidence' should be a dict")
        else:
            if "level" not in confidence:
                result.warn("'confidence' missing 'level' field")
            elif confidence["level"] not in VALID_CONFIDENCE_LEVELS:
                result.warn(
                    f"'confidence.level' should be one of {VALID_CONFIDENCE_LEVELS}, "
                    f"got: '{confidence['level']}'"
                )
            if "reasoning" not in confidence:
                result.warn("'confidence' missing 'reasoning' field")
            if "what_i_cannot_verify" not in confidence:
                result.warn("'confidence' missing 'what_i_cannot_verify' field")

    # Soft-required: story_dod for SE/QE. Without it the Evidence/DoD gate
    # scoreboard at /quality has no signal for that story.
    role_for_dod = receipt.get("role") if isinstance(receipt.get("role"), str) else None
    if "story_dod" in receipt:
        story_dod = receipt["story_dod"]
        if not isinstance(story_dod, dict):
            result.warn("'story_dod' should be a dict mapping DoD check IDs to booleans")
        else:
            for k, v in story_dod.items():
                if not isinstance(v, bool):
                    result.warn(f"'story_dod.{k}' should be a boolean, got: {type(v).__name__}")
                if k not in KNOWN_STORY_DOD_KEYS:
                    result.warn(
                        f"'story_dod.{k}' is not one of the canonical DoD checks "
                        f"({sorted(KNOWN_STORY_DOD_KEYS)}); it will be ignored by the Evidence-gate rollup"
                    )
            # #199: an ABSENT contractual key was previously invisible — only
            # unknown keys and a wholly missing block warned. Across a real
            # 11-day prod window (296 receipts carrying story_dod) that let
            # four of the five canonical checks reach ZERO occurrences while
            # agents invented their own keys, so /quality's Evidence gate was
            # scoring one signal out of five and nothing said so.
            #
            # Reported as one warning rather than one per key: a receipt with
            # only `tests_pass` would otherwise emit four, drowning the rest of
            # the validation output.
            if role_for_dod in ROLES_REQUIRING_STORY_DOD:
                absent = sorted(KNOWN_STORY_DOD_KEYS - set(story_dod))
                if absent:
                    result.warn(
                        f"'story_dod' omits {len(absent)} of the "
                        f"{len(KNOWN_STORY_DOD_KEYS)} canonical DoD checks: "
                        f"{absent}. The /quality Evidence gate has no signal for "
                        "these, so the story scores as unevaluated on them rather "
                        "than passing — report each one explicitly, including "
                        "`false`."
                    )
    elif role_for_dod in ROLES_REQUIRING_STORY_DOD:
        result.warn(
            f"'story_dod' missing — role '{role_for_dod}' should populate it so "
            "/quality Evidence-gate scoreboard has a signal for this story"
        )

    _validate_runtime_identity_overlay(receipt, project_dir, result)

    _validate_typed_evidence(receipt, result)

    # Soft-required: token_usage. Without it the Cost dashboard at
    # /cost shows $0 for this row even when work was done.
    # Warn-now-error-later: in-flight receipts written by older plugin
    # versions still pass; new receipts SHOULD include the block.
    if "token_usage" in receipt:
        tu = receipt["token_usage"]
        if not isinstance(tu, dict):
            result.warn(
                "'token_usage' should be a dict like "
                "{input, output, cache_read, cache_write, stage}"
            )
        else:
            for k in ("input", "output", "cache_read", "cache_write"):
                v = _token_usage_value(tu, k)
                if v is None:
                    result.warn(f"'token_usage.{k}' missing — defaults to 0 in cost rollup")
                    continue
                if not isinstance(v, int) or isinstance(v, bool) or v < 0:
                    result.warn(
                        f"'token_usage.{k}' should be a non-negative int, got: {v!r}"
                    )
            stage = tu.get("stage")
            stage_valid = (
                isinstance(stage, str) and stage.strip() and stage in VALID_V3_STAGES
            )
            if not stage_valid:
                # GAP-7 (#163) × #158/#159: when a canonical v3 stage can be
                # inferred — from the receipt's role (evidence contract, then
                # ROLE_STAGE_FALLBACK) or an unambiguous stage prefix — the
                # SubagentStop hook backfills it locally before shipping
                # (transcript_usage.patch_receipt) and the CP remaps at
                # ingest as belt-and-braces, so warning here would just be
                # per-receipt noise. The warning is kept only when nothing
                # can be inferred (unknown or multi-stage roles like
                # project-owner).
                canonical_stage = None
                role_for_stage = receipt.get("role")
                if _evidence_contract is not None and isinstance(role_for_stage, str):
                    try:
                        canonical_stage = _evidence_contract.role_stage(role_for_stage)
                    except Exception:
                        canonical_stage = None
                if not canonical_stage:
                    canonical_stage = _canonical_stage_hint(stage, role_for_dod)
                if not canonical_stage:
                    if not isinstance(stage, str) or not stage.strip():
                        result.warn(
                            "'token_usage.stage' missing — row will roll up under 'unknown' "
                            "in /cost by-stage"
                        )
                    else:
                        result.warn(
                            f"'token_usage.stage' '{stage}' is not a v3 stage "
                            f"(expected one of {sorted(VALID_V3_STAGES)})"
                        )
    else:
        result.warn(
            "'token_usage' missing — /cost will show $0 for this receipt. "
            "Populate {input, output, cache_read, cache_write, stage} so spend rolls up."
        )

    # Optional: fallback_from (backend fallback tracing)
    if "fallback_from" in receipt:
        fallback = receipt["fallback_from"]
        if not isinstance(fallback, str):
            result.warn("'fallback_from' should be a string (original backend name)")

    return result


if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(f"Usage: {sys.argv[0]} <receipt.json> <project_dir>", file=sys.stderr)
        sys.exit(1)

    receipt_path = sys.argv[1]
    project_dir = sys.argv[2]
    result = validate_receipt(receipt_path, project_dir)
    print(json.dumps(result.to_dict(), indent=2))
    sys.exit(0 if result.valid else 1)
